  public static func createDSS(
    _ fbb: inout FlatBufferBuilder,
    STATUS: dssSyncState = .idle,
    SYNCED_ROWS: UInt64 = 0,
    TOTAL_ROWS: UInt64 = 0,
    LOCAL_ROWS: UInt64 = 0,
    PINNED_ROWS: UInt64 = 0,
    MISSING_ROWS: UInt64 = 0,
    CACHED_BYTES: UInt64 = 0,
    PINNED_BYTES: UInt64 = 0,
    DOWNLOADED_BYTES: UInt64 = 0,
    DOWNLOAD_SPEED_BYTES_PER_SECOND: UInt64 = 0,
    MEASURED_WIRE_SPEED_BYTES_PER_SECOND: UInt64 = 0,
    HAS_WIRE_SPEED_UTILIZATION: Bool = false,
    WIRE_SPEED_UTILIZATION: Double = 0.0,
    WIRE_SPEED_TARGET: Double = 0.0,
    HAS_WIRE_SPEED_TARGET_MET: Bool = false,
    WIRE_SPEED_TARGET_MET: Bool = false,
    MANIFEST_DISCOVERY_MS: UInt64 = 0,
    NETWORK_TRANSFER_MS: UInt64 = 0,
    VERIFICATION_MS: UInt64 = 0,
    FLATSQL_MATERIALIZATION_MS: UInt64 = 0,
    PROVIDER_PEER_IDOffset PROVIDER_PEER_ID: Offset = Offset(),
    PROVIDER_PUBLIC_KEYOffset PROVIDER_PUBLIC_KEY: Offset = Offset(),
    SNAPSHOT_IDOffset SNAPSHOT_ID: Offset = Offset(),
    HEADOffset HEAD: Offset = Offset(),
    CURSOROffset CURSOR: Offset = Offset(),
    NEXT_CURSOROffset NEXT_CURSOR: Offset = Offset(),
    HIGH_WATER_MARKOffset HIGH_WATER_MARK: Offset = Offset(),
    QUERY_PROFILEOffset QUERY_PROFILE: Offset = Offset(),
    CHUNK_HASHOffset CHUNK_HASH: Offset = Offset(),
    SYNC_PROTOCOLOffset SYNC_PROTOCOL: Offset = Offset(),
    SYNC_FILTEROffset SYNC_FILTER: Offset = Offset(),
    VERIFIED_CHUNKSVectorOffset VERIFIED_CHUNKS: Offset = Offset(),
    LAST_SYNCED_ATOffset LAST_SYNCED_AT: Offset = Offset(),
    ERROROffset ERROR: Offset = Offset(),
    SCHEMA_NAMEOffset SCHEMA_NAME: Offset = Offset(),
    PROVIDER_IDOffset PROVIDER_ID: Offset = Offset(),
    SOURCE_NAMEOffset SOURCE_NAME: Offset = Offset(),
    DATASET_IDOffset DATASET_ID: Offset = Offset(),
    CONNECTOR_IDOffset CONNECTOR_ID: Offset = Offset(),
    CHANNEL_IDOffset CHANNEL_ID: Offset = Offset(),
    TOPICOffset TOPIC: Offset = Offset(),
    SUBSCRIBED: Bool = false,
    PIN_POLICY: dssPinPolicy = .none_,
    VISIBILITYOffset VISIBILITY: Offset = Offset(),
    ENCRYPTION_STATEOffset ENCRYPTION_STATE: Offset = Offset(),
    GRANT_STATEOffset GRANT_STATE: Offset = Offset(),
    FEED_HEADOffset FEED_HEAD: Offset = Offset(),
    LAST_PUBLICATION_CIDOffset LAST_PUBLICATION_CID: Offset = Offset(),
    LAST_PNM_CIDOffset LAST_PNM_CID: Offset = Offset(),
    DELTA_ROWS: UInt64 = 0,
    LAST_SYNC_STARTED_AT: UInt64 = 0,
    REQUESTED_ACTION: dssAction = .none_,
    ORIGIN_IDOffset ORIGIN_ID: Offset = Offset()
  ) -> Offset {
    let __start = DSS.startDSS(&fbb)
    DSS.add(STATUS: STATUS, &fbb)
    DSS.add(SYNCED_ROWS: SYNCED_ROWS, &fbb)
    DSS.add(TOTAL_ROWS: TOTAL_ROWS, &fbb)
    DSS.add(LOCAL_ROWS: LOCAL_ROWS, &fbb)
    DSS.add(PINNED_ROWS: PINNED_ROWS, &fbb)
    DSS.add(MISSING_ROWS: MISSING_ROWS, &fbb)
    DSS.add(CACHED_BYTES: CACHED_BYTES, &fbb)
    DSS.add(PINNED_BYTES: PINNED_BYTES, &fbb)
    DSS.add(DOWNLOADED_BYTES: DOWNLOADED_BYTES, &fbb)
    DSS.add(DOWNLOAD_SPEED_BYTES_PER_SECOND: DOWNLOAD_SPEED_BYTES_PER_SECOND, &fbb)
    DSS.add(MEASURED_WIRE_SPEED_BYTES_PER_SECOND: MEASURED_WIRE_SPEED_BYTES_PER_SECOND, &fbb)
    DSS.add(HAS_WIRE_SPEED_UTILIZATION: HAS_WIRE_SPEED_UTILIZATION, &fbb)
    DSS.add(WIRE_SPEED_UTILIZATION: WIRE_SPEED_UTILIZATION, &fbb)
    DSS.add(WIRE_SPEED_TARGET: WIRE_SPEED_TARGET, &fbb)
    DSS.add(HAS_WIRE_SPEED_TARGET_MET: HAS_WIRE_SPEED_TARGET_MET, &fbb)
    DSS.add(WIRE_SPEED_TARGET_MET: WIRE_SPEED_TARGET_MET, &fbb)
    DSS.add(MANIFEST_DISCOVERY_MS: MANIFEST_DISCOVERY_MS, &fbb)
    DSS.add(NETWORK_TRANSFER_MS: NETWORK_TRANSFER_MS, &fbb)
    DSS.add(VERIFICATION_MS: VERIFICATION_MS, &fbb)
    DSS.add(FLATSQL_MATERIALIZATION_MS: FLATSQL_MATERIALIZATION_MS, &fbb)
    DSS.add(PROVIDER_PEER_ID: PROVIDER_PEER_ID, &fbb)
    DSS.add(PROVIDER_PUBLIC_KEY: PROVIDER_PUBLIC_KEY, &fbb)
    DSS.add(SNAPSHOT_ID: SNAPSHOT_ID, &fbb)
    DSS.add(HEAD: HEAD, &fbb)
    DSS.add(CURSOR: CURSOR, &fbb)
    DSS.add(NEXT_CURSOR: NEXT_CURSOR, &fbb)
    DSS.add(HIGH_WATER_MARK: HIGH_WATER_MARK, &fbb)
    DSS.add(QUERY_PROFILE: QUERY_PROFILE, &fbb)
    DSS.add(CHUNK_HASH: CHUNK_HASH, &fbb)
    DSS.add(SYNC_PROTOCOL: SYNC_PROTOCOL, &fbb)
    DSS.add(SYNC_FILTER: SYNC_FILTER, &fbb)
    DSS.addVectorOf(VERIFIED_CHUNKS: VERIFIED_CHUNKS, &fbb)
    DSS.add(LAST_SYNCED_AT: LAST_SYNCED_AT, &fbb)
    DSS.add(ERROR: ERROR, &fbb)
    DSS.add(SCHEMA_NAME: SCHEMA_NAME, &fbb)
    DSS.add(PROVIDER_ID: PROVIDER_ID, &fbb)
    DSS.add(SOURCE_NAME: SOURCE_NAME, &fbb)
    DSS.add(DATASET_ID: DATASET_ID, &fbb)
    DSS.add(CONNECTOR_ID: CONNECTOR_ID, &fbb)
    DSS.add(CHANNEL_ID: CHANNEL_ID, &fbb)
    DSS.add(TOPIC: TOPIC, &fbb)
    DSS.add(SUBSCRIBED: SUBSCRIBED, &fbb)
    DSS.add(PIN_POLICY: PIN_POLICY, &fbb)
    DSS.add(VISIBILITY: VISIBILITY, &fbb)
    DSS.add(ENCRYPTION_STATE: ENCRYPTION_STATE, &fbb)
    DSS.add(GRANT_STATE: GRANT_STATE, &fbb)
    DSS.add(FEED_HEAD: FEED_HEAD, &fbb)
    DSS.add(LAST_PUBLICATION_CID: LAST_PUBLICATION_CID, &fbb)
    DSS.add(LAST_PNM_CID: LAST_PNM_CID, &fbb)
    DSS.add(DELTA_ROWS: DELTA_ROWS, &fbb)
    DSS.add(LAST_SYNC_STARTED_AT: LAST_SYNC_STARTED_AT, &fbb)
    DSS.add(REQUESTED_ACTION: REQUESTED_ACTION, &fbb)
    DSS.add(ORIGIN_ID: ORIGIN_ID, &fbb)
    return DSS.endDSS(&fbb, start: __start)
  }

